private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    // Convert to array for indexed access
    Object[] verts = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V vi = (V) verts[i];
        for (int j = i + 1; j < size; j++) {
            V vj = (V) verts[j];
            boolean edgeExists;
            try {
                // Prefer containsEdge if available
                edgeExists = graph.containsEdge(vi, vj);
            } catch (UnsupportedOperationException e) {
                // Fallback to getEdge
                edgeExists = graph.getEdge(vi, vj) != null;
            }
            if (!edgeExists) {
                return false;
            }
        }
    }
    return true;
}

