        } catch (Exception e1) {
            try {
                java.lang.reflect.Constructor<?> ctor = PathSegmentImpl.class.getConstructor(String.class);
                segmentObj = (PathSegmentImpl) ctor.newInstance(seg);
            } catch (Exception e2) {
                // If no suitable constructor, skip this segment
                continue;
            }
        }
        if (segmentObj != null) {
            result.add(segmentObj);
        }
    }
    return result;
}

