@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV,String dir){
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null) {
        throw new IllegalArgumentException("Directory path cannot be null");
    }
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a directory: " + dir);
    }
    File[] files = directory.listFiles();
    if (files == null) {
        return;
    }
    for (File f : files) {
        if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
            try {
                cpV.add(f.toURI().toURL());
            } catch (MalformedURLException e) {
                // Skip files that cannot be converted to URL
            } catch (SecurityException e) {
                // Skip files that cannot be accessed due to security restrictions
            }
        }
    }
}

