public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return null;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Determine if the original path is absolute (starts with '/')
    boolean leadingSlash = path.startsWith("/");
    // Remove trailing slashes from the base path (except when the path is just "/")
    while (path.length() > 1 && path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the base path and relative path into components
    String[] baseParts = path.split("/");
    String[] relParts = relativePath.split("/");

    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Process base path components
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Process relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If the result is empty, return "." to represent the current directory
    if (result.length() == 0) {
        return ".";
    }
    return result.toString();
}

